INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(350581, 28003, 6202, '<td valign="top">I love it, just shows how many of us hang out here =o) Little blurry but cool concept</td>', 'I love it, just shows how many of us hang out here =o) Little blurry but cool concept', '2003-07-09 01:03:45.000000', NULL, 1),
(350585, 27968, 6202, '<td valign="top">Nice shot.  love the park bench photos! 10</td>', 'Nice shot.  love the park bench photos! 10', '2003-07-09 01:05:46.000000', NULL, 1),
(350595, 28003, 9146, '<td valign="top">pandering to your audiance.....I like that</td>', 'pandering to your audiance.....I like that', '2003-07-09 01:12:42.000000', NULL, 1),
(350597, 27530, 9146, '<td valign="top">ahhhh</td>', 'ahhhh', '2003-07-09 01:13:22.000000', NULL, 1),
(350599, 27625, 9232, '<td valign="top">I like the coloration and the angles on this.  Good composition.<br/> <br/>I think I would like to see the same picture but with someone standing outside, maybe smiling at the photographer.  I think that would humanize the picture and draw the view into the setting more.</td>', 'I like the coloration and the angles on this.  Good composition. I think I would like to see the same picture but with someone standing outside, maybe smiling at the photographer.  I think that would humanize the picture and draw the view into the setting more.', '2003-07-09 01:15:06.000000', NULL, 1),
(350600, 27335, 9232, '<td valign="top">Good idea, but the surface where the reflections are is blurry.  Maybe I''m just missing something on the righthand side of the photo.</td>', 'Good idea, but the surface where the reflections are is blurry.  Maybe I''m just missing something on the righthand side of the photo.', '2003-07-09 01:16:02.000000', NULL, 1),
(350603, 27870, 9232, '<td valign="top">Good composition and I like the cropping you chose.  Cutting out the right edge of the glass and the back of the woman''s head give this image an edginess that makes the viewer feel like he''s in the photo''s action.<br/> <br/>I wish the image wasn''t so grainy but I''m guessing that is a product of the size limitations.<br/> <br/>Good idea and good execution.</td>', 'Good composition and I like the cropping you chose.  Cutting out the right edge of the glass and the back of the woman''s head give this image an edginess that makes the viewer feel like he''s in the photo''s action. I wish the image wasn''t so grainy but I''m guessing that is a product of the size limitations. Good idea and good execution.', '2003-07-09 01:17:41.000000', NULL, 1),
(350605, 27927, 9146, '<td valign="top">very evocative of van gogh</td>', 'very evocative of van gogh', '2003-07-09 01:20:36.000000', NULL, 1),
(350611, 27839, 9146, '<td valign="top">Could use a little more mood lighting</td>', 'Could use a little more mood lighting', '2003-07-09 01:23:17.000000', NULL, 1),
(350612, 27750, 9232, '<td valign="top">Wow.<br/> <br/>The image just begs you to enter it from the left side and then the starkness of the right side slams you back to remind you that you''re seeing a photo.  This image works on so many levels for me I find it difficult to explain.<br/> <br/>Firstly the architecture is superb.  You selected a great subject and shot it from a wonderful perspective.  You caught the curved railing perfectly to use it to make the viewer feel the picture is organic and responsive in nature.  The equally lined righthand side utilizes straight lines and brightness to uses more defined angles and straight edges to engender a feeling of mental rigidity.<br/> <br/>The only thing I would be interested in seeing different is cropping the front of the boat out of the lefthand side of the image.  <br/> <br/>Great eye</td>', 'Wow. The image just begs you to enter it from the left side and then the starkness of the right side slams you back to remind you that you''re seeing a photo.  This image works on so many levels for me I find it difficult to explain. Firstly the architecture is superb.  You selected a great subject and shot it from a wonderful perspective.  You caught the curved railing perfectly to use it to make the viewer feel the picture is organic and responsive in nature.  The equally lined righthand side utilizes straight lines and brightness to uses more defined angles and straight edges to engender a feeling of mental rigidity. The only thing I would be interested in seeing different is cropping the front of the boat out of the lefthand side of the image.   Great eye', '2003-07-09 01:23:44.000000', NULL, 1),
(350621, 27898, 7175, '<td valign="top">I would have given this photo at least 2 points more if the "open" sign was on... not too much fun on the twn if it''s closed.. :)</td>', 'I would have given this photo at least 2 points more if the "open" sign was on... not too much fun on the twn if it''s closed.. :)', '2003-07-09 01:29:00.000000', NULL, 1),
(350624, 27970, 7175, '<td valign="top">This is a great shot, but isn''t the challenge for a NIGHT on the town?</td>', 'This is a great shot, but isn''t the challenge for a NIGHT on the town?', '2003-07-09 01:29:32.000000', NULL, 1),
(350625, 27933, 811, '<td valign="top">Aw geez, now I have that song in my head!!<br/> <br/>"Sometimes you wanna go, where everybody knows your name . ...."<br/> <br/>I like the reflection in the sign though.</td>', 'Aw geez, now I have that song in my head!! "Sometimes you wanna go, where everybody knows your name . ...." I like the reflection in the sign though.', '2003-07-09 01:30:06.000000', NULL, 1),
