(350630, 27334, 7175, '<td valign="top">Cute!</td>', 'Cute!', '2003-07-09 01:31:12.000000', NULL, 1),
(350635, 27977, 9854, '<td valign="top">Wow. this is one of thos aaah pictures. I like the way you left the man out, and made him just a hint  of a nice guy reflected on the woman''s face. Looks like mystery guy hit first base.</td>', 'Wow. this is one of thos aaah pictures. I like the way you left the man out, and made him just a hint  of a nice guy reflected on the woman''s face. Looks like mystery guy hit first base.', '2003-07-09 01:32:49.000000', NULL, 1),
(350638, 27975, 7504, '<td valign="top">Yeah, all that, only I''d add a Snickers too.  Hmm, maybe a Symphony bar is better.  Actually, Ben and Jerry''s would round things out nicely.  That''s my kind of "Night on the Town"!</td>', 'Yeah, all that, only I''d add a Snickers too.  Hmm, maybe a Symphony bar is better.  Actually, Ben and Jerry''s would round things out nicely.  That''s my kind of "Night on the Town"!', '2003-07-09 01:34:30.000000', NULL, 1),
(350639, 27457, 9854, '<td valign="top">niceI love the hi-hat on the lady.  Picture captures the moment well. Good dof.</td>', 'niceI love the hi-hat on the lady.  Picture captures the moment well. Good dof.', '2003-07-09 01:35:10.000000', NULL, 1),
(350642, 27534, 7291, '<td valign="top">Hey, I can see my house in the distance!  Just kidding.  That''s Highwy 115 near Ft. Carson isn''t it?  Nice pic.  A little noisy but it''s nice.</td>', 'Hey, I can see my house in the distance!  Just kidding.  That''s Highwy 115 near Ft. Carson isn''t it?  Nice pic.  A little noisy but it''s nice.', '2003-07-09 01:37:24.000000', NULL, 1),
