(350657, 27530, 6900, '<td valign="top">Wow, such wonderful models!  Such beautiful lighting.  Such romance, such love....anyways, beautiful gorgeous picture.  I want this framed, on my desk.  It''s absolutely the best pic of us together that exists.  Thank you for TAKING it.  - 15.</td>', 'Wow, such wonderful models!  Such beautiful lighting.  Such romance, such love....anyways, beautiful gorgeous picture.  I want this framed, on my desk.  It''s absolutely the best pic of us together that exists.  Thank you for TAKING it.  - 15.', '2003-07-09 01:51:55.000000', NULL, 1),
(350660, 27882, 7175, '<td valign="top">This would have been a much better photo on a time-lapse tripod, so the background would be in focus... 4</td>', 'This would have been a much better photo on a time-lapse tripod, so the background would be in focus... 4', '2003-07-09 01:55:34.000000', NULL, 1),
(350663, 27815, 7175, '<td valign="top">well done!</td>', 'well done!', '2003-07-09 01:56:33.000000', NULL, 1),
