(350689, 27640, 9854, '<td valign="top">Extra sharp! Nice contrast.</td>', 'Extra sharp! Nice contrast.', '2003-07-09 02:05:57.000000', NULL, 1),
(350691, 27642, 9854, '<td valign="top">Looks like a winner to me. Excellent foto.</td>', 'Looks like a winner to me. Excellent foto.', '2003-07-09 02:07:16.000000', NULL, 1),
(350694, 27921, 9854, '<td valign="top">The sheen and ripples have texturized the water surface like a glossy pavement.  nice contrasts... B/W is seldom effective for fireworks (to my taste), but this one''s an exception.</td>', 'The sheen and ripples have texturized the water surface like a glossy pavement.  nice contrasts... B/W is seldom effective for fireworks (to my taste), but this one''s an exception.', '2003-07-09 02:10:46.000000', NULL, 1),
