(350700, 27884, 9687, '<td valign="top">I would have prefered this without the border</td>', 'I would have prefered this without the border', '2003-07-09 02:13:26.000000', NULL, 1),
(350704, 27789, 5964, '<td valign="top">This is my top pick of this challenge, I love how you have captured a beautiful setting with bustling nightlife.  I think there are a few too many lens flares, or what appears to be flares, but beyond that exceptional. The longer exposure really works too it really makes the whoe pic come to life. 9.</td>', 'This is my top pick of this challenge, I love how you have captured a beautiful setting with bustling nightlife.  I think there are a few too many lens flares, or what appears to be flares, but beyond that exceptional. The longer exposure really works too it really makes the whoe pic come to life. 9.', '2003-07-09 02:15:13.000000', NULL, 1),
