INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(351803, 27884, 6464, '<td valign="top">Nice image.  I think the border takes away from it.</td>', 'Nice image.  I think the border takes away from it.', '2003-07-09 20:25:57.000000', NULL, 1),
