(351819, 27534, 6464, '<td valign="top">Doesn''t have identifiable subject.</td>', 'Doesn''t have identifiable subject.', '2003-07-09 20:34:44.000000', NULL, 1),
(351820, 27802, 6150, '<td valign="top">This is a great shot.  Meets the challenge nicely.  The reflection on the water is beautiful.  Looks so peaceful for a big city.  Good luck in the challenge.</td>', 'This is a great shot.  Meets the challenge nicely.  The reflection on the water is beautiful.  Looks so peaceful for a big city.  Good luck in the challenge.', '2003-07-09 20:35:03.000000', NULL, 1),
(351821, 27921, 772, '<td valign="top">This is a beautiful capture... I simply love the silhouetted peoplein the foreground of this shot... It reminds me quite a bit of Gordon''s ''bellagio'' submission a while back in that aspect... I also think your choice of a duotone in this image also works very well... great shot... = 10</td>', 'This is a beautiful capture... I simply love the silhouetted peoplein the foreground of this shot... It reminds me quite a bit of Gordon''s ''bellagio'' submission a while back in that aspect... I also think your choice of a duotone in this image also works very well... great shot... = 10', '2003-07-09 20:35:11.000000', NULL, 1),
(351823, 27628, 6464, '<td valign="top">Nice exposure to capture motion and sky.  The hotspot near bottom-left is somewhat distracting.  Fits theme well.</td>', 'Nice exposure to capture motion and sky.  The hotspot near bottom-left is somewhat distracting.  Fits theme well.', '2003-07-09 20:35:44.000000', NULL, 1),
(351824, 27970, 772, '<td valign="top">I can''t find any relatonship to the challenge in this photograph.  So, basically, this comment is actually a wast of time since I''m sure you will get plenty like it.</td>', 'I can''t find any relatonship to the challenge in this photograph.  So, basically, this comment is actually a wast of time since I''m sure you will get plenty like it.', '2003-07-09 20:36:18.000000', NULL, 1),
