(351833, 27878, 6464, '<td valign="top">I think it''s creative, but doesn''t result in an eye-catching image.</td>', 'I think it''s creative, but doesn''t result in an eye-catching image.', '2003-07-09 20:45:44.000000', NULL, 1),
(351835, 27805, 6464, '<td valign="top">Nice abstract.  I''m not sure if it fits the theme perfectly, but I like it.</td>', 'Nice abstract.  I''m not sure if it fits the theme perfectly, but I like it.', '2003-07-09 20:49:33.000000', NULL, 1),
